CREATE TABLE IF NOT EXISTS examination_panels (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(150) NOT NULL,
    description VARCHAR(255) NULL,
    is_always_included TINYINT(1) NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    display_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY examination_panels_code_unique (code),
    KEY examination_panels_active_order_index (is_active, display_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS test_parameters (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    panel_id BIGINT UNSIGNED NOT NULL,
    code VARCHAR(64) NOT NULL,
    label VARCHAR(150) NOT NULL,
    subsection VARCHAR(150) NULL,
    result_type ENUM('numeric', 'text', 'select') NOT NULL,
    unit VARCHAR(32) NULL,
    options_json LONGTEXT NULL,
    legacy_field VARCHAR(64) NULL,
    is_required TINYINT(1) NOT NULL DEFAULT 0,
    print_when_empty TINYINT(1) NOT NULL DEFAULT 1,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    display_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY test_parameters_code_unique (code),
    KEY test_parameters_panel_order_index (panel_id, is_active, display_order),
    CONSTRAINT test_parameters_panel_foreign FOREIGN KEY (panel_id) REFERENCES examination_panels(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO examination_panels
    (code, name, description, is_always_included, is_active, display_order, created_at, updated_at)
VALUES
    ('hematology_complete', 'DL / Darah Lengkap / Hematologi', 'Hematologi, hitung jenis leukosit, dan indeks eritrosit.', 0, 1, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
    ('urinalysis_complete', 'Urine Lengkap / Urinalisis', 'Pemeriksaan makroskopis, kimia, dan sedimen urine.', 0, 1, 20, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
    ('clinical_chemistry', 'Kimia Klinik', 'Glukosa, lipid, fungsi ginjal, dan enzim hati.', 0, 1, 30, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
    ('widal', 'Widal / Pemeriksaan Terkait Demam Tifoid', 'Pemeriksaan Widal O, AO, BO, dan H.', 0, 1, 40, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
    ('additional_rare', 'Pemeriksaan Tambahan', 'Pemeriksaan opsional yang lebih jarang digunakan.', 0, 1, 50, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
    ('immunoserology', 'Imunoserologi', 'Selalu tersedia pada form dan selalu tercetak.', 1, 1, 60, UTC_TIMESTAMP(), UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    description = VALUES(description),
    is_always_included = VALUES(is_always_included),
    is_active = VALUES(is_active),
    display_order = VALUES(display_order),
    updated_at = UTC_TIMESTAMP();

